import {preferences,keys,write} from './state.mjs';
import {esc,icon} from './ui.mjs';
import {defaults,normalizeSettings} from './settings-model.mjs';
import {validateBackup,planMerge,backupLabels,backupLimit} from './backup-model.mjs';
import {currentBackup,fingerprint,restoreBackup} from './backup-service.mjs';
const $=s=>document.querySelector(s);let session;
export function clearSettingsWork(){session=null;}
export const settingsHasWork=()=>!!(session&&(session.dirty||session.busy));
export function settingsRouteGuard(target){if(!session)return true;const s=session;if(s.busy){s.ctx.notify('正在处理备份，请稍候。');return false;}if(!s.dirty)return true;s.ctx.modal('设置尚未保存','<p class="hub-description">离开前，可以保存这次修改，或放弃修改。</p><div class="settings-actions"><button class="btn secondary" id="settings-stay">继续设置</button><button class="btn secondary" id="settings-discard">放弃修改</button><button class="btn primary" id="settings-save-leave">保存并离开</button></div>');$('#settings-stay').onclick=()=>$('#workspace-dialog').close();$('#settings-discard').onclick=()=>{s.dirty=false;$('#workspace-dialog').close();location.hash=target;};$('#settings-save-leave').onclick=()=>{if(save(s)){ $('#workspace-dialog').close();location.hash=target;}};return false;}
window.addEventListener('beforeunload',e=>{if(settingsHasWork()){e.preventDefault();e.returnValue='';}});
function save(s){try{write(keys.preferences,{...preferences(),...s.values});s.original={...s.values};s.dirty=false;s.ctx.apply();status('设置已保存 · 仅应用于当前浏览器');s.ctx.notify('设置已保存。');return true;}catch{status('保存失败，请检查浏览器存储空间。',true);return false;}}
function status(message,error=false){const el=$('#settings-status');if(el){el.textContent=message;el.classList.toggle('error',error);}}
function preview(s){const box=$('#settings-example');if(box){box.dataset.density=s.values.density;box.dataset.font=s.values.fontSize;}s.dirty=JSON.stringify(s.values)!==JSON.stringify(s.original);status(s.dirty?'有未保存的修改':'设置已保存于当前浏览器');}
const choice=(name,value,label,description,current)=>`<label class="settings-choice"><input type="radio" name="${name}" value="${value}" ${current===value?'checked':''}><span><b>${label}</b>${description?`<small>${description}</small>`:''}</span></label>`;
export function mountSettings(ctx,section){const tab=section==='privacy'||section==='data'?'data':section==='writing'?'writing':'interface';const values=normalizeSettings(preferences());const s=session={ctx,tab,values,original:{...values},dirty:false,busy:false};$('.dashboard').onclick=null;$('.dashboard').innerHTML=`<div class="hub-heading"><div><h1>设置中心</h1><p>让工作空间更适合你的研究习惯。</p></div><span class="settings-local">${icon('shield',16)} 当前浏览器生效</span></div><nav class="settings-tabs" aria-label="设置分类">${[['writing','写作偏好','pen'],['interface','界面偏好','grid'],['data','数据与备份','shield']].map(([id,label,i])=>`<a href="#settings/${id}" ${tab===id?'aria-current="page"':''}>${icon(i,18)}${label}</a>`).join('')}</nav><div class="settings-layout"><section class="card settings-main">${tab==='data'?dataPanel():preferencePanel(s)}</section><aside class="settings-aside"><section class="card"><span class="more-icon blue">${icon('settings',24)}</span><h3>设置的生效范围</h3><p>写作默认值用于新建项目与任务。界面偏好在保存后生效，已有内容不会被改写。</p></section><section class="card"><h3>让研究资料有备份</h3><p>当前资料保存在此浏览器。更换设备或清理数据前，先导出工作空间备份。</p><a href="#settings/data">管理数据与备份 →</a></section><section class="card"><h3>账户与服务</h3><a href="#account">个人资料与账户 →</a><a href="#membership">会员与用量 →</a><small>在线账户、支付与云同步尚未接入。</small></section></aside></div><div id="settings-status" class="settings-status" role="status" aria-live="polite">设置已保存于当前浏览器</div>`;
if(tab==='data'){bindData(s);status('导出备份，或选择备份文件进行校验。');return;}$('#settings-form').oninput=()=>{s.values=normalizeSettings({...s.values,...Object.fromEntries(new FormData($('#settings-form')))});preview(s);};$('#settings-form').onsubmit=e=>{e.preventDefault();save(s);};$('#settings-reset').onclick=()=>{ctx.modal('恢复当前分类的默认设置','<p class="hub-description">只重置当前分类的偏好，不删除项目或成果。重置后需要点击保存。</p><button class="btn primary" id="confirm-settings-reset">恢复默认</button>');$('#confirm-settings-reset').onclick=()=>{for(const key of tab==='writing'?['degree','major']:['density','fontSize'])s.values[key]=defaults[key];const f=$('#settings-form');for(const [key,value]of Object.entries(s.values)){const field=f.elements.namedItem(key);if(field)field.value=value;}preview(s);$('#workspace-dialog').close();};};preview(s);}
function preferencePanel(s){return `<h2>${s.tab==='writing'?'写作偏好':'界面偏好'}</h2><p class="settings-description">${s.tab==='writing'?'设置常用学段与专业，减少重复填写。':'选择适合你的信息密度与阅读字号。'}</p><form id="settings-form" class="hub-form">${s.tab==='writing'?`<label for="setting-degree">默认学段</label><select name="degree" id="setting-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===s.values.degree?'selected':''}>${d}</option>`).join('')}</select><label for="setting-major">默认学科专业</label><input name="major" id="setting-major" maxlength="100" value="${esc(s.values.major)}" placeholder="例如：教育学"><p class="hub-footnote">只影响新建内容；每次任务仍可单独调整。</p>`:`<fieldset><legend>列表显示密度</legend><div class="settings-choices">${choice('density','comfortable','舒适','留白充足，便于浏览',s.values.density)}${choice('density','compact','紧凑','更集中地查看记录',s.values.density)}</div></fieldset><fieldset><legend>界面字号</legend><div class="settings-choices font-choices">${choice('fontSize','normal','标准','',s.values.fontSize)}${choice('fontSize','large','较大','',s.values.fontSize)}${choice('fontSize','larger','更大','',s.values.fontSize)}</div></fieldset><div class="settings-preview-title">效果预览 <small>示例内容，不会保存为项目</small></div><div id="settings-example"><header>最近项目 <span>预览</span></header><div>${icon('folder',24)}<span><b>我的毕业论文研究</b><small>本科 · 教育学 · 最近编辑</small></span><em>进行中</em></div><div>${icon('file',24)}<span><b>文献综述与研究框架</b><small>论文大纲 · 可继续编辑</small></span><em>草稿</em></div></div><p class="hub-footnote">预览仅作用于上方示例，保存后应用到工作空间。</p>`}<footer class="settings-actions"><button type="button" id="settings-reset" class="btn secondary">恢复默认</button><button class="btn primary" type="submit">保存设置</button></footer></form>`;}
function dataPanel(){return `<h2>数据与备份</h2><p class="settings-description">把研究资料带走，也能从备份中继续。</p><div class="settings-storage"><span>${icon('shield',24)}</span><div><b>资料保存在当前浏览器</b><p>项目、草稿、文献笔记与报告在本地保存；论文文件本地解析，不自动上传。云端同步尚未接入。</p></div></div><h3>导出工作空间</h3><p class="settings-description">包含项目、成果草稿、文献与笔记、任务、报告正文、个人资料、偏好与工具收藏。备份可能包含私人研究资料，请妥善保管。</p><button class="btn secondary" id="settings-export">${icon('file',17)} 导出备份</button><hr><h3>从备份恢复</h3><p class="settings-description">上传 PaperKnow 备份 JSON，先预览，再合并新增记录。重复编号保留当前版本，不覆盖已有内容。</p><label class="settings-upload" for="settings-file">${icon('upload',28)}<b>选择备份文件</b><span>JSON · 最大 50 MB · 版本 1</span><input id="settings-file" type="file" accept=".json,application/json"></label><div id="settings-import-preview"></div><p class="hub-footnote">备份仅覆盖已保存的内容，不包含所有上传原件；未保存的编辑内容需要先保存。</p>`;}
function bindData(s){$('#settings-export').onclick=async()=>{if(s.busy)return;s.busy=true;try{await s.ctx.exportBackup();}finally{s.busy=false;}};$('#settings-file').onchange=async e=>{const file=e.target.files[0];if(!file||s.busy)return;s.busy=true;$('#settings-import-preview').innerHTML='';status('正在校验备份…');try{if(file.size>backupLimit)throw Error('备份超过 50 MB，请选择较小的备份。');const incoming=validateBackup(JSON.parse(await file.text()));const current=await currentBackup();if(session!==s)return;const plan=planMerge(current,incoming),expected=fingerprint(current);$('#settings-import-preview').innerHTML=`<div class="settings-import"><h3>备份预览</h3><p>${esc(file.name)} · ${Math.ceil(file.size/1024)} KB</p><table><thead><tr><th>内容</th><th>新增</th><th>重复跳过</th></tr></thead><tbody>${plan.summary.map(r=>`<tr><td>${backupLabels[r.key]}</td><td>${r.added}</td><td>${r.skipped}</td></tr>`).join('')}</tbody></table>${plan.orphaned?`<p class="error">${plan.orphaned} 条记录关联的项目不在备份或当前空间中，关联暂无法显示。</p>`:''}<label><input type="checkbox" id="settings-personal"> 同时恢复个人资料与偏好（将替换对应设置）</label><p class="hub-footnote">工具收藏会合并；已有项目、成果和报告保留当前版本。</p><button class="btn primary" id="settings-import">确认合并恢复</button><button class="btn secondary" id="settings-import-cancel">取消</button></div>`;$('#settings-import-cancel').onclick=()=>{$('#settings-import-preview').innerHTML='';e.target.value='';status('已取消，当前数据未改变。');};$('#settings-import').onclick=async()=>{if(s.busy)return;s.busy=true;$('#settings-import').disabled=true;status('正在恢复，请勿关闭页面…');try{const summary=await restoreBackup(incoming,expected,{restorePersonal:$('#settings-personal').checked});$('#settings-import-preview').innerHTML='';e.target.value='';status(`恢复完成：新增 ${summary.reduce((n,r)=>n+r.added,0)} 条记录，重复记录已跳过。`);try{await s.ctx.restored();}catch{s.ctx.notify('记录已恢复，但刷新报告列表失败，请重新打开工作台。');}}catch(error){status(error.message||'恢复失败。',true);}finally{s.busy=false;if($('#settings-import'))$('#settings-import').disabled=false;}};status('校验通过，请核对预览后确认恢复。');}catch(error){status(error instanceof SyntaxError?'文件不是有效的 JSON 备份。':error.message,true);e.target.value='';}finally{s.busy=false;}};}
